1: //! A least-recently-used cache with a fixed capacity.
2: 
3: pub struct Lru {
4:     cap: usize,
5:     /// Keys in use order, least-recent FIRST.
6:     order: Vec<String>,
7:     vals: Vec<(String, i64)>,
8: }
9: 
10: impl Lru {
11:     pub fn new(cap: usize) -> Self {
12:         Lru {
13:             cap,
14:             order: Vec::new(),
15:             vals: Vec::new(),
16:         }
17:     }
18: 
19:     fn touch(&mut self, key: &str) {
20:         self.order.push(key.to_string());
21:     }
22: 
23:     pub fn get(&mut self, key: &str) -> Option<i64> {
24:         let found = self.vals.iter().find(|(k, _)| k == key).map(|(_, v)| *v);
25:         if found.is_some() {
26:             self.touch(key);
27:         }
28:         found
29:     }
30: 
31:     pub fn put(&mut self, key: &str, val: i64) {
32:         if let Some(e) = self.vals.iter_mut().find(|(k, _)| k == key) {
33:             e.1 = val;
34:             self.touch(key);
35:             return;
36:         }
37:         if self.vals.len() == self.cap {
38:             let evict = self.order.remove(0);
39:             self.vals.retain(|(k, _)| *k != evict);
40:         }
41:         self.vals.push((key.to_string(), val));
42:         self.order.push(key.to_string());
43:     }
44: 
45:     /// Keys currently held, least-recently-used first.
46:     pub fn keys(&self) -> Vec<String> {
47:         self.order.clone()
48:     }
49: }

