{"tool": "write_file", "path": "test.rs", "new_str":"// Test cases for A* pathfinding

use pathfind::{astar_bool_grid, astar_bool_grid_8};

#[test]
fn start_equals_goal_is_an_empty_path() {
    let width = 3;
    let height = 3;
    let blocked = [false; 9];
    let start = (1, 1);
    let goal = (1, 1);
    let path = astar_bool_grid_8(width, height, &blocked, start, goal);
    assert_eq!(path, Some(vec![]));
}

#[test]
fn a_straight_line_is_unchanged_by_diagonals() {
    let width = 5;
    let height = 5;
    let blocked = [false; 25];
    let start = (0, 0);
    let goal = (4, 0);
    let path_4conn = astar_bool_grid(width, height, &blocked, start, goal);
    let path_8conn = astar_bool_grid_8(width, height, &blocked, start, goal);
    assert_eq!(path_4conn, path_8conn);
}

#[test]
fn a_diagonal_run_is_shorter_than_the_4_connected_one() {
    let width = 5;
    let height = 5;
    let blocked = [false; 25];
    let start = (0, 0);
    let goal = (4, 4);
    let path_4conn = astar_bool_grid(width, height, &blocked, start, goal);
    let path_8conn = astar_bool_grid_8(width, height, &blocked, start, goal);
    assert!(path_8conn.unwrap().len() < path_4conn.unwrap().len());
}

#[test]
fn the_path_excludes_the_start_and_includes_the_goal() {
    let width = 3;
    let height = 3;
    let blocked = [false; 9];
    let start = (0, 0);
    let goal = (2, 2);
    let path = astar_bool_grid_8(width, height, &blocked, start, goal);
    assert!(path.is_some());
    let path = path.unwrap();
    assert_eq!(path[0], (0, 1));
    assert_eq!(path[path.len() - 1], (2, 2));
}

#[test]
fn every_step_moves_at_most_one_cell_in_each_axis() {
    let width = 3;
    let height = 3;
    let blocked = [false; 9];
    let start = (0, 0);
    let goal = (2, 2);
    let path = astar_bool_grid_8(width, height, &blocked, start, goal);
    assert!(path.is_some());
    let path = path.unwrap();
    for i in 0..path.len() - 1 {
        let (c1, r1) = path[i];
        let (c2, r2) = path[i + 1];
        assert!((c2 as i32 - c1 as i32).abs() <= 1);
        assert!((r2 as i32 - r1 as i32).abs() <= 1);
    }
}

#[test]
fn a_blocked_goal_is_unreachable() {
    let width = 3;
    let height = 3;
    let mut blocked = [false; 9];
    blocked[8] = true; // goal is blocked
    let start = (0, 0);
    let goal = (2, 2);
    let path = astar_bool_grid_8(width, height, &blocked, start, goal);
    assert_eq!(path, None);
}

#[test]
fn it_routes_around_a_wall() {
    let width = 3;
    let height = 3;
    let mut blocked = [false; 9];
    blocked[4] = true; // wall in the middle
    let start = (0, 0);
    let goal = (2, 2);
    let path = astar_bool_grid_8(width, height, &blocked, start, goal);
    assert!(path.is_some());
    let path = path.unwrap();
    // The path should go around the wall
    assert!(path.contains(&(0, 1)));
    assert!(path.contains(&(1, 1)));
    assert!(path.contains(&(2, 1)));
}

#[test]
fn an_enclosed_goal_is_unreachable() {
    let width = 3;
    let height = 3;
    let mut blocked = [false; 9];
    blocked[0] = true; // left wall
    blocked[1] = true; // left wall
    blocked[3] = true; // bottom wall
    blocked[4] = true; // middle wall
    blocked[6] = true; // top wall
    blocked[7] = true; // right wall
    let start = (1, 1);
    let goal = (1, 1);
    let path = astar_bool_grid_8(width, blocked, start, goal);
    assert_eq!(path, None);
}","path": "test.rs"}}

