1: //! Grid A* pathfinding for on-foot NPC navigation (game side).
2: //!
3: //! 4-connected (N/S/E/W), uniform cost 1 per step, Manhattan heuristic.
4: //! Operates on a `Floor` — walkable iff `!TileKind::blocks()`.
5: //! Out-of-bounds tiles read as `Empty` (blocking).
6: //!
7: //! Returned path excludes the start tile and includes the goal, in tile
8: //! coords as `(u16, u16)`. Empty `Vec` when start == goal. `None` when
9: //! unreachable.
10: //!
11: //! The A* kernel itself lives in `pathfind` as the generic
12: //! `astar_tile_grid` over a `TileSource` trait. This module provides the
13: //! game-side `TileSource` impls and thin wrappers.
14: 
15: use std::collections::HashSet;
16: 
17: #[path = "pathfind.rs"]
18: pub mod pathfind;
19: 
20: use pathfind::{astar_tile_grid, TileSource};
21: 
22: /// What a tile is made of.
23: #[derive(Debug, Clone, Copy, PartialEq, Eq)]
24: pub enum TileKind {
25:     /// Off-grid interior, or open vacuum on an exterior floor.
26:     Empty,
27:     /// Walkable station floor.
28:     Floor,
29:     /// Solid.
30:     Wall,
31:     /// A docking pad — walkable, but the dock pathfinder may block it.
32:     Pad,
33: }
34: 
35: impl TileKind {
36:     /// True if a unit on foot cannot enter this tile.
37:     pub fn blocks(self) -> bool {
38:         !matches!(self, TileKind::Floor | TileKind::Pad)
39:     }
40: }
41: 
42: /// A rectangular tile floor.
43: pub struct Floor {
44:     w: u32,
45:     h: u32,
46:     tiles: Vec<TileKind>,
47: }
48: 
49: impl Floor {
50:     pub fn new(w: u32, h: u32, tiles: Vec<TileKind>) -> Self {
51:         assert_eq!(tiles.len(), (w * h) as usize, "tile count must match dims");
52:         Floor { w, h, tiles }
53:     }
54:     pub fn width(&self) -> u32 { self.w }
55:     pub fn height(&self) -> u32 { self.h }
56:     /// Tile at `(c, r)`; out-of-bounds reads as `Empty`.
57:     pub fn tile_at(&self, c: i32, r: i32) -> TileKind {
58:         if c < 0 || r < 0 || c >= self.w as i32 || r >= self.h as i32 {
59:             return TileKind::Empty;
60:         }
61:         self.tiles[(r as u32 * self.w + c as u32) as usize]
62:     }
63: }
64: 
65: /// Interior-floor `TileSource`: reads `TileKind::blocks()`.
66: struct InteriorSource<'a>(&'a Floor);
67: 
68: impl<'a> TileSource for InteriorSource<'a> {
69:     fn dims(&self) -> (u32, u32) { (self.0.width(), self.0.height()) }
70:     fn blocks(&self, c: i32, r: i32) -> bool { self.0.tile_at(c, r).blocks() }
71: }
72: 
73: /// Exterior-floor `TileSource`: `Empty` (vacuum) and `Pad` are walkable;
74: /// everything else is blocking. Out-of-bounds reads block too.
75: struct ExteriorSource<'a>(&'a Floor);
