160:     /// Iterate every cell as `(col, row, val)` in row-major scan order.
161:     pub fn iter_cells(&self) -> impl Iterator<Item = (u32, u32, T)> + '_ {
162:         let w = self.w;
163:         self.grid.iter().enumerate().map(move |(i, &v)| {
164:             let i = i as u32;
165:             (i % w, i / w, v)
