169:     /// Rebuild storage from a row-major provider. `w` / `h` are set to
170:     /// the passed dims and every cell is filled by calling `read(c, r)`.
171:     /// The standard use is decoding a `Vec<String>` of glyphs into
172:     /// enum tiles — pass a closure that indexes into the strings, or
173:     /// prefer [`TileGrid::rebuild_from_glyphs`] which handles that
174:     /// pattern directly.
175:     pub fn rebuild_from_rows<F>(&mut self, w: u32, h: u32, mut read: F)
176:     where
177:         F: FnMut(u32, u32) -> T,
178:     {
179:         self.w = w;
180:         self.h = h;
181:         let mut buf = Vec::with_capacity((w * h) as usize);
182:         for r in 0..h {
183:             for c in 0..w {
184:                 buf.push(read(c, r));
185:             }
186:         }
187:         self.grid = buf;
188:     }
