190:     /// Rebuild from a `&[String]` of glyph rows via a `char -> T`
191:     /// decoder. Dims are derived from the string vec (height = row
192:     /// count, width = first row's byte length). Bytes past a short
193:     /// row and unmapped chars fall through to `T::default()`. Every
194:     /// tile-file loader in the project (station floors, ship
195:     /// interiors, module tiles) shares this exact decode path.
196:     pub fn rebuild_from_glyphs<F>(&mut self, tiles: &[String], mut decode: F)
197:     where
198:         F: FnMut(char) -> T,
199:     {
200:         let h = tiles.len() as u32;
201:         let w = tiles.first().map(|r| r.len() as u32).unwrap_or(0);
202:         self.rebuild_from_rows(w, h, |c, r| {
203:             tiles.get(r as usize)
204:                 .and_then(|row| row.as_bytes().get(c as usize).copied())
205:                 .map(|b| decode(b as char))
206:                 .unwrap_or_default()
207:         });
208:     }
