210:     /// Read a `(col, row)` from a `&[String]` of glyph rows without a
211:     /// prebuilt grid. Returns `T::default()` for out-of-range or short
212:     /// rows. Used by the `tile_at` fallback path on fresh-from-`serde`
213:     /// instances where `rebuild_from_glyphs` hasn't run yet.
214:     pub fn tile_at_glyphs<F>(tiles: &[String], col: i32, row: i32, mut decode: F) -> T
215:     where
216:         F: FnMut(char) -> T,
217:     {
218:         if col < 0 || row < 0 { return T::default(); }
219:         tiles.get(row as usize)
220:             .and_then(|s| s.as_bytes().get(col as usize).copied())
221:             .map(|b| decode(b as char))
222:             .unwrap_or_default()
223:     }
