192:     /// count, width = first row's byte length). Bytes past a short
193:     /// row and unmapped chars fall through to `T::default()`. Every
194:     /// tile-file loader in the project (station floors, ship
195:     /// interiors, module tiles) shares this exact decode path.
196:     pub fn rebuild_from_glyphs<F>(&mut self, tiles: &[String], mut decode: F)
197:     where
198:         F: FnMut(char) -> T,
199:     {
