242: /// Rotate a row-major `w * h` tile buffer by `rot` quarter-turns
243: /// clockwise (taken modulo 4), returning `(new_w, new_h, tiles)`.
244: ///
245: /// Odd quarter-turns transpose the dimensions. `rot == 0` is a straight
246: /// copy. Reads go through `src`, a `(col, row) -> T` closure, rather
247: /// than a slice, so callers whose canonical storage is glyph rows or a
248: /// lazily-populated cache can rotate without materialising a flat buffer
249: /// first.
250: ///
251: /// Extracted because `void_sim::module::Module::rotated_tiles` and the
252: /// tilemap editor's `Clipboard::rotated` carried byte-identical copies
253: /// of this kernel, and a divergence between them would silently desync
254: /// the editor preview from the runtime composite.
255: pub fn rotate_tiles<T, F>(w: u32, h: u32, rot: u8, mut src: F) -> (u32, u32, Vec<T>)
256: where
257:     T: Copy + Default,
258:     F: FnMut(u32, u32) -> T,
259: {
260:     let rot = rot % 4;
261:     let (sw, sh) = (w as usize, h as usize);
262:     let (nw, nh) = match rot {
263:         1 | 3 => (sh, sw),
264:         _     => (sw, sh),
265:     };
266:     let mut out = vec![T::default(); nw * nh];
267:     for r in 0..sh {
268:         for c in 0..sw {
269:             let val = src(c as u32, r as u32);
270:             let (nc, nr) = match rot {
271:                 0 => (c, r),
272:                 1 => (sh - 1 - r, c),          // 90° CW
273:                 2 => (sw - 1 - c, sh - 1 - r), // 180°
274:                 3 => (r, sw - 1 - c),          // 270° CW (= 90° CCW)
275:                 _ => unreachable!(),
276:             };
277:             out[nr * nw + nc] = val;
278:         }
279:     }
280:     (nw as u32, nh as u32, out)
281: }

