1: //! Byte-span arithmetic shared by everything that slices source text.
2: 
3: /// A half-open byte span `[start, end)` into some source string.
4: #[derive(Debug, Clone, Copy, PartialEq, Eq)]
5: pub struct Span {
6:     pub start: usize,
7:     pub end: usize,
8: }
9: 
10: impl Span {
11:     pub fn new(start: usize, end: usize) -> Self {
12:         Span { start, end }
13:     }
14: 
15:     /// The number of bytes this span covers.
16:     pub fn len(&self) -> usize {
17:         self.end - self.start
18:     }
19: }
20: 
21: /// The span of the line containing byte offset `at`, excluding the newline that
22: /// ends it.
23: pub fn line_span(text: &str, at: usize) -> Span {
24:     let start = text[..at].rfind('\n').map(|i| i + 1).unwrap_or(0);
25:     let end = match text[at..].find('\n') {
26:         Some(i) => at + i,
27:         None => text.len(),
28:     };
29:     Span::new(start, end)
30: }
31: 
32: /// How many chunks of at most `width` bytes it takes to cover `len` bytes.
33: ///
34: /// A zero-length input still needs one (empty) chunk, so callers always have
35: /// something to render.
36: pub fn chunk_count(len: usize, width: usize) -> usize {
37:     if width == 0 {
38:         return 1;
39:     }
40:     len / width + 1
41: }

